#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

/**
 * Problem: 10605 - Count the Trees
 * 
 * 解題思路：
 * 1. n 個節點的二元樹形狀數量為卡特蘭數 C_n = (1/(n+1)) * (2n! / (n! * n!))。
 * 2. 如果節點是有標籤的 (labeled)，則對於每一種形狀，n 個標籤有 n! 種排列方式。
 * 3. 因此總數為 C_n * n! = (2n!) / (n+1)!。
 * 4. n 最大 300，需要使用大數運算。
 */

struct BigInt {
    vector<int> digits;
    BigInt(long long n = 0) {
        if (n == 0) digits.push_back(0);
        while (n > 0) {
            digits.push_back(n % 10);
            n /= 10;
        }
    }
    void multiply(int n) {
        int carry = 0;
        for (int i = 0; i < (int)digits.size(); ++i) {
            long long prod = (long long)digits[i] * n + carry;
            digits[i] = prod % 10;
            carry = prod / 10;
        }
        while (carry) {
            digits.push_back(carry % 10);
            carry /= 10;
        }
    }
    void divide(int n) {
        int rem = 0;
        for (int i = (int)digits.size() - 1; i >= 0; --i) {
            long long curr = digits[i] + (long long)rem * 10;
            digits[i] = curr / n;
            rem = curr % n;
        }
        while (digits.size() > 1 && digits.back() == 0) digits.pop_back();
    }
    void print() {
        for (int i = (int)digits.size() - 1; i >= 0; --i) cout << digits[i];
        cout << endl;
    }
};

int main() {
    int n;
    while (cin >> n && n != 0) {
        BigInt res(1);
        // 計算 (2n)! / (n+1)!
        // 即 (n+2) * (n+3) * ... * (2n)
        for (int i = n + 2; i <= 2 * n; ++i) res.multiply(i);
        res.print();
    }
    return 0;
}
